sys_script_include.script:
var CompanyDetailsUtils = Class.create();
// Add global. before AbstractAjaxProcessor
CompanyDetailsUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getCompanyBranches: function() {
        var companyId = this.getParameter('sysparm_company_id');
        if (!companyId) return '';

        // Replace 'core_company' with your actual company table backend name if custom
        var companyGr = new GlideRecord('core_company'); 
        if (companyGr.get(companyId)) {
            // Replace 'allow_branches' with the exact backend column name on the company table
            return companyGr.getValue('allow_branches') || '';
        }
        return '';
    },

    type: 'CompanyDetailsUtils'
});
